#!/usr/bin/env bash
set -euo pipefail
cd "$(cd "$(dirname "$0")/.." && pwd)"

cat <<'B64' | base64 -d | gzip -d > /tmp/v085.patch

B64
patch -p1 < /tmp/v085.patch

sed -i "s/versionCode [0-9][0-9]*/versionCode 85/" app/build.gradle
sed -i "s/versionName '[^']*'/versionName '0.85.0'/" app/build.gradle

node -e "const fs=require('fs');const h=fs.readFileSync('app/src/main/assets/index.html','utf8');const s=[...h.matchAll(/<script(?:\\s[^>]*)?>([\\s\\S]*?)<\\/script>/gi)].map(x=>x[1]).join('\\n');fs.writeFileSync('/tmp/lakenav-v085-inline.js',s)"
node --check /tmp/lakenav-v085-inline.js

grep -q 'v0.85' app/src/main/assets/index.html
grep -q 'returnTrackGeometryProjection' app/src/main/assets/index.html
grep -q 'join the recorded line anywhere' app/src/main/assets/index.html
grep -q 'Follow is released only' app/src/main/assets/index.html

printf 'LakeNav WI v0.85 return-track line following and follow-mode reliability applied.\n'
